import heapq


def _dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        domains = []
        for name in names:
            versions = [row["version"] for row in packages[name]
                        if row["version"] not in blocked.get(name, [])
                        and (name not in pins or row["version"] == pins[name])]
            domains.append([None] + versions)

        best_key = None
        best_versions = None
        for values in product(*domains):
            choice = dict(zip(names, values))
            valid = True
            graph = {}
            for name, bounds in data["roots"].items():
                version = choice[name]
                if version is None or not bounds[0] <= version <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue

            installed = {name for name, version in choice.items() if version is not None}
            for name in installed:
                row = next(r for r in packages[name] if r["version"] == choice[name])
                deps = [d for d in row.get("deps", [])
                        if not d.get("feature") or d["feature"] in features]
                graph[name] = []
                for dep in deps:
                    target = choice[dep["name"]]
                    if target is None or not dep["min"] <= target <= dep["max"]:
                        valid = False
                        break
                    graph[name].append(dep["name"])
                if not valid:
                    break
            if not valid:
                continue

            closure = set()
            stack = list(data["roots"])
            while stack:
                name = stack.pop()
                if name in closure:
                    continue
                closure.add(name)
                stack.extend(graph.get(name, []))
            if closure != installed:
                continue

            visiting, visited = set(), set()
            def acyclic(name):
                if name in visiting:
                    return False
                if name in visited:
                    return True
                visiting.add(name)
                if any(not acyclic(other) for other in graph.get(name, [])):
                    return False
                visiting.remove(name)
                visited.add(name)
                return True
            if not all(acyclic(name) for name in installed):
                continue

            ordered = names if name_order == "ascending" else list(reversed(names))
            key = tuple(choice[name] if choice[name] is not None else -1 for name in ordered)
            if best_key is None or (key > best_key if preference == "maximum" else key < best_key):
                best_key = key
                best_versions = {name: choice[name] for name in installed}

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _round(numerator, mode):
    if mode == "floor":
        return numerator // 10000
    return (numerator + 5000) // 10000


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), data["rounding"])
        tax = _round(net * event.get("tax_bp", 0), data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _quotas(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    available = [j for j in jobs if j["id"] not in blocked]
    best_value = None
    best_ids = None
    for subset in combinations(available, k):
        ids = [j["id"] for j in subset]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
        active_ends = []
        overlap_ok = True
        for job in ordered:
            active_ends = [end for end in active_ends if end > job["start"]]
            if len(active_ends) >= 2:
                overlap_ok = False
                break
            active_ends.append(job["end"])
        if not overlap_ok:
            continue
        value = sum(j["value"] for j in subset)
        selected = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    start = data["start"]
    distances = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], coupons)]
            if coupons:
                options.append((max(2, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, left))
    return {"arrival": None}


